  V('بسنده کردن', 'yetinmek', 'به کتاب‌های شهر خود بسنده نکرد.', 'Kendi şehrinin kitaplarıyla yetinmedi.', 'basande kardan'), V('شرح‌حال', 'biyografi, tercüme-i hâl', 'شرح‌حال او را در کتاب‌ها خواندم.', 'Onun biyografisini kitaplarda okudum.', 'şarh-e hâl'),
