  V('فشرده', 'yoğun, sıkıştırılmış', 'زبان او فشرده است.', 'Onun dili yoğundur.', 'feşorde'), V('رستاخیز', 'kıyamet, diriliş', 'روز رستاخیز پاسخگو خواهی بود.', 'Kıyamet günü hesap vereceksin.', 'rastâkhiz'),
